[data-project-transition=tab] .task-board-column:nth-child(n+4) [data-task-card] { animation-delay:.09s; }

/* Original .fx-route owns catalogue/Favorites direct-child entry and progress, Overview stack segments and Timeline bars. The shared scale-based
   fill preserves its underlying value at the end of growX. */
[data-project-page-motion][data-project-transition=route] > * { animation:riseIn .36s var(--ease) both; }
[data-project-page-motion][data-project-transition=route] > :nth-child(2) { animation-delay:.035s; }
[data-project-page-motion][data-project-transition=route] > :nth-child(3) { animation-delay:.07s; }
[data-project-page-motion][data-project-transition=route] > :nth-child(n+4) { animation-delay:.1s; }
[data-project-transition=route] [role=progressbar] > i, [data-project-transition=route] [data-project-stackedbar] i { animation:growX .8s .12s var(--ease) both; }
[data-project-transition=route] [data-timeline-bar] { animation:riseIn .4s var(--ease) both; }
:root[data-motion=reduce] [data-project-page-motion][data-project-transition] > *, :root[data-motion=reduce] [data-project-transition=route] [data-timeline-bar] { animation:fadeOnly .12s both; }
:root[data-motion=reduce] [data-project-transition=route] [role=progressbar] > i, :root[data-motion=reduce] [data-project-transition=route] [data-project-stackedbar] i { animation:none; }
@media(prefers-reduced-motion:reduce) {
 :root:not([data-motion=full]) [data-project-page-motion][data-project-transition] > *, :root:not([data-motion=full]) [data-project-transition=route] [data-timeline-bar] { animation:fadeOnly .12s both; }
 :root:not([data-motion=full]) [data-project-transition=route] [role=progressbar] > i, :root:not([data-motion=full]) [data-project-transition=route] [data-project-stackedbar] i { animation:none; }
}

/* Native Source input focus/blur uses the CSS default ease, not route easing. */
[data-project-catalogue] input, [data-project-form] input, [data-project-form] textarea, [data-project-share] input, [data-project-saved-dialog] input, [data-project-host] input { transition:border-color var(--dur),box-shadow var(--dur); }
[data-project-form] [aria-label=Close], [data-project-share] [aria-label=Close], [data-project-saved-dialog] [aria-label=Close] { transition:background var(--dur),color var(--dur); }
.project-templates > button { transition:border-color var(--dur),box-shadow var(--dur),background var(--dur); }
